      align: 'center',
      letterSpacing: 0.015,
    });
    if (textObj) {
      textObj.position.set(0, 0, 0.02);
      // animate text opacity
      textObj.traverse(o => {
        if (o.material) {
          o.material.transparent = true;
          o.material.opacity = 0;
        }
      });
      group.add(textObj);
    }
  }

